const r = $("fetch_employees");
const rows = (r && r.data) || [];
const recipients = rows
  .filter(function (row) { return !!row.phoneNumber; })
  .map(function (row) {
    return { phoneNumber: row.phoneNumber, parameters: { EMPLOYEE_NAME: row.name || '' } };
  });
return { employeeCount: recipients.length, recipients: recipients };

