const departmentFound = ($("check_department") || {}).departmentFound === true;
const employeesCheck = $("check_employees") || {};
const notified = departmentFound && (employeesCheck.employeeCount || 0) > 0;
return {
  success: true,
  message: notified
    ? 'The Fuel department has been notified.'
    : "We couldn't find anyone in the Fuel department right now, but you've been told.",
  stateParams: {
    notified: notified,
    recipientCount: employeesCheck.employeeCount || 0
  }
};
